// Reaches `unsafe` first in source order, then `net`.
import { wrappingMul } from "nish:unsafe";
import { netAddress, tcpConnect } from "nish:net";

const mix = (h: i32): i32 => wrappingMul(h, 31);

export const both = (port: i32): i32 => {
  const addr: u8[] = [];
  return netAddress(addr, "127.0.0.1", mix(port)) >= 0 && tcpConnect(addr) >= 0 ? 1 : 0;
};
